<!DOCTYPE html>
<html lang="zh-Hant">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>享哥 AI 虛擬助理</title>
<style>
  :root {
    --ink: #172033;
    --muted: #667085;
    --line: rgba(23, 32, 51, .12);
    --surface: rgba(255, 255, 255, .96);
    --panel: rgba(17, 24, 39, .76);
    --accent: #2563eb;
    --accent-strong: #1d4ed8;
    --success: #0f766e;
  }

  * { box-sizing: border-box; }

  html,
  body {
    width: 100%;
    height: 100%;
    margin: 0;
    overflow: hidden;
    background: transparent;
    color: var(--ink);
    font-family: "Noto Sans TC", "Noto Sans", system-ui, -apple-system, BlinkMacSystemFont, sans-serif;
    -webkit-font-smoothing: antialiased;
  }

  #stage {
    position: absolute;
    inset: 0;
    overflow: hidden;
  }

  #assistant-avatar {
    appearance: none;
    position: absolute;
    z-index: 1;
    right: 86px;
    bottom: 58px;
    width: 206px;
    height: 286px;
    margin: 0;
    padding: 0;
    border: 0;
    background: transparent;
    cursor: pointer;
    transform-origin: 50% 100%;
    animation: avatar-idle 5.6s ease-in-out infinite;
    pointer-events: auto;
  }

  #assistant-avatar svg {
    width: 100%;
    height: 100%;
    display: block;
    overflow: visible;
    filter: drop-shadow(0 18px 24px rgba(17, 24, 39, .18));
  }

  .avatar-head {
    transform-origin: 150px 126px;
    animation: avatar-head-idle 4.8s ease-in-out infinite;
  }

  .avatar-eye {
    transform-origin: center;
    animation: avatar-blink 5.2s infinite;
  }

  .avatar-mouth {
    transform-origin: 150px 153px;
    transition: transform .12s ease, opacity .12s ease;
  }

  .avatar-mouth-open {
    opacity: 0;
    transform: scaleY(.3);
  }

  body.speaking #assistant-avatar {
    animation-duration: 2.4s;
  }

  body.speaking .avatar-head {
    animation: avatar-speaking-head .7s ease-in-out infinite;
  }

  body.speaking .avatar-mouth-closed {
    opacity: 0;
  }

  body.speaking .avatar-mouth-open {
    opacity: 1;
    animation: avatar-talk .18s ease-in-out infinite alternate;
  }

  body.listening .avatar-listen-ring {
    opacity: .55;
    animation: avatar-pulse 1.2s ease-out infinite;
  }

  .avatar-listen-ring {
    opacity: 0;
    transform-origin: 150px 142px;
  }

  @keyframes avatar-idle {
    0%, 100% { transform: translateY(0); }
    50% { transform: translateY(-5px); }
  }

  @keyframes avatar-head-idle {
    0%, 100% { transform: rotate(0deg); }
    48% { transform: rotate(-1.4deg); }
    58% { transform: rotate(1.1deg); }
  }

  @keyframes avatar-speaking-head {
    0%, 100% { transform: translateY(0) rotate(0deg); }
    50% { transform: translateY(2px) rotate(.8deg); }
  }

  @keyframes avatar-blink {
    0%, 7%, 9%, 100% { transform: scaleY(1); }
    8% { transform: scaleY(.08); }
  }

  @keyframes avatar-talk {
    from { transform: scaleY(.55); }
    to { transform: scaleY(1.25); }
  }

  @keyframes avatar-pulse {
    from { transform: scale(.96); opacity: .45; }
    to { transform: scale(1.2); opacity: 0; }
  }

  #bubble {
    position: absolute;
    z-index: 2;
    top: 10px;
    left: 10px;
    right: 10px;
    min-height: 62px;
    max-height: 112px;
    padding: 10px 12px;
    border: 1px solid rgba(23, 32, 51, .1);
    border-radius: 12px;
    background: var(--surface);
    box-shadow: 0 14px 34px rgba(17, 24, 39, .16);
    font-size: 13px;
    line-height: 1.48;
    overflow: hidden;
    opacity: 0;
    transform: translateY(-8px);
    transition: opacity .2s ease, transform .2s ease;
    pointer-events: none;
  }

  #bubble.show {
    opacity: 1;
    transform: translateY(0);
  }

  #suggestions {
    position: absolute;
    z-index: 3;
    left: 10px;
    right: 10px;
    bottom: 70px;
    width: auto;
    display: flex;
    flex-direction: row;
    flex-wrap: wrap;
    gap: 6px;
    align-items: center;
    justify-content: center;
  }

  .suggestion {
    appearance: none;
    border: 1px solid rgba(37, 99, 235, .22);
    border-radius: 999px;
    background: rgba(255, 255, 255, .94);
    color: var(--accent-strong);
    box-shadow: 0 8px 20px rgba(17, 24, 39, .14);
    cursor: pointer;
    font: 700 10px/1.1 "Noto Sans TC", system-ui, sans-serif;
    padding: 6px 8px;
    max-width: 126px;
    text-align: center;
    white-space: normal;
  }

  .suggestion:hover { background: #fff; transform: translateY(-1px); }
  .suggestion:focus-visible { outline: 3px solid rgba(37, 99, 235, .3); outline-offset: 2px; }

  #control-bar {
    position: absolute;
    z-index: 4;
    right: 12px;
    bottom: 10px;
    display: flex;
    flex-direction: row;
    gap: 6px;
    align-items: center;
    width: auto;
    padding: 6px;
    border-radius: 14px;
    background: var(--panel);
    box-shadow: 0 16px 36px rgba(17, 24, 39, .26), inset 0 0 0 1px rgba(255, 255, 255, .12);
    backdrop-filter: blur(12px) saturate(1.3);
    -webkit-backdrop-filter: blur(12px) saturate(1.3);
  }

  .control {
    appearance: none;
    height: 34px;
    min-width: 42px;
    border: 0;
    border-radius: 10px;
    background: rgba(255, 255, 255, .14);
    color: #fff;
    cursor: pointer;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    padding: 0 9px;
    font: 800 12px/1 "Noto Sans TC", system-ui, sans-serif;
    white-space: nowrap;
  }

  .control.primary {
    min-width: 62px;
    background: var(--accent);
  }

  .control:hover { background: rgba(255, 255, 255, .24); }
  .control.primary:hover { background: var(--accent-strong); }
  .control:focus-visible { outline: 3px solid rgba(255, 255, 255, .55); outline-offset: 2px; }
  .control.listening { background: var(--success); }

  @media (max-width: 420px) {
    #bubble { font-size: 12px; max-height: 104px; }
    #assistant-avatar { right: 78px; bottom: 58px; width: 198px; height: 276px; }
    #suggestions { bottom: 70px; gap: 5px; }
    .suggestion { max-width: 126px; font-size: 10px; padding: 6px 8px; }
    .control { min-width: 38px; padding: 0 8px; font-size: 12px; }
    .control.primary { min-width: 56px; }
  }
</style>
</head>
