  <script>
    (function () {
      'use strict';

      var query = new URLSearchParams(window.location.search);
      var KNOWLEDGE_URL = query.get('knowledge') || '';
      var VOICE_HINT = query.get('voice') || 'male';
      var kb = Array.isArray(window.HSIANG_AVATAR_KB) ? window.HSIANG_AVATAR_KB : [];
      var isSpeaking = false;
      var muted = false;
      var ttsRate = 1;
      var selectedVoice = null;
      var recognition = null;
      var listening = false;
      var SpeechRecognitionApi = window.SpeechRecognition || window.webkitSpeechRecognition;

      if (KNOWLEDGE_URL) {
        fetch(KNOWLEDGE_URL)
          .then(function (response) { return response.ok ? response.json() : null; })
          .then(function (items) { if (Array.isArray(items)) kb = items; })
          .catch(function () {});
      }

      function post(type, payload) {
        try {
          window.parent.postMessage(Object.assign({ ns: 'hsiang-avatar', type: type }, payload || {}), '*');
        } catch (error) {}
      }

      function showBubble(text, timeout) {
        var bubble = document.getElementById('bubble');
        bubble.textContent = text;
        bubble.classList.add('show');
        window.clearTimeout(showBubble.timer);
        showBubble.timer = window.setTimeout(function () {
          bubble.classList.remove('show');
        }, timeout || 7200);
      }

      function normalize(text) {
        return String(text || '').toLowerCase().replace(/[\s，。、？！,.?!：:；;「」『』（）()]/g, '');
      }

      function bigrams(text) {
        var source = normalize(text);
        var grams = [];
        if (!source) return grams;
        if (source.length === 1) return [source];
        for (var i = 0; i < source.length - 1; i += 1) grams.push(source.slice(i, i + 2));
        return grams;
      }

      function similarity(queryText, targetText) {
        var a = bigrams(queryText);
        var b = new Set(bigrams(targetText));
        if (!a.length || !b.size) return 0;
        var hits = 0;
        a.forEach(function (gram) { if (b.has(gram)) hits += 1; });
        return hits / Math.sqrt(a.length * b.size);
      }

      function scoreEntry(text, entry) {
        var score = Math.max(similarity(text, entry.q), similarity(text, entry.kw || ''));
        var queryText = normalize(text);
        String(entry.kw || '').split(/\s+/).forEach(function (term) {
          if (term.length >= 2 && queryText.indexOf(normalize(term)) !== -1) {
            score = Math.max(score, .52 + Math.min(term.length * .035, .25));
          }
        });
        return score;
      }

      function answer(text) {
        var trimmed = String(text || '').trim();
        var best = null;
        var bestScore = 0;
        if (!trimmed) return '我好像沒有聽清楚，可以再說一次嗎？';
        kb.forEach(function (entry) {
          var score = scoreEntry(trimmed, entry);
          if (score > bestScore) {
            best = entry;
            bestScore = score;
          }
        });
        if (best && bestScore >= .14) return best.a;
        return '這題我目前還沒有完整資料。你可以先問我 AI 顧問、n8n 自動化、企業內訓、費用或預約諮詢。';
      }

      function loadVoice() {
        if (!('speechSynthesis' in window)) return;
        var voices = window.speechSynthesis.getVoices();
        var preferredTaiwanMaleNames = ['Eddy', 'Grandpa', 'Rocko', 'Reed', 'YunJhe', '雲哲', 'Zhiwei', 'Kangkang'];
        var fallbackTaiwanMale = /Eddy|Microsoft|Male|男/i;
        var femaleVoice = /Hsiao|Xiao|Yating|HanHan|MeiJia|Meijia|美佳|Flo|Grandma|Sandy|Shelley|Female|女/i;
        function findVoiceByNames(langPattern, names) {
          for (var i = 0; i < names.length; i += 1) {
            var pattern = new RegExp(names[i], 'i');
            var found = voices.find(function (voice) {
              return langPattern.test(voice.lang) && pattern.test(voice.name) && !femaleVoice.test(voice.name);
            });
            if (found) return found;
          }
          return null;
        }
        selectedVoice =
          voices.find(function (voice) { return VOICE_HINT !== 'male' && new RegExp(VOICE_HINT, 'i').test(voice.name + ' ' + voice.lang); }) ||
          findVoiceByNames(/zh[-_]TW/i, preferredTaiwanMaleNames) ||
          findVoiceByNames(/^zh/i, preferredTaiwanMaleNames) ||
          voices.find(function (voice) { return /zh[-_]TW/i.test(voice.lang) && fallbackTaiwanMale.test(voice.name) && !femaleVoice.test(voice.name); }) ||
          voices.find(function (voice) { return /zh[-_]TW/i.test(voice.lang); }) ||
          voices.find(function (voice) { return /zh/i.test(voice.lang); }) ||
          voices.find(function (voice) { return voice.lang === VOICE_HINT; }) ||
          null;
        window.__selectedVoiceName = selectedVoice ? selectedVoice.name + ' / ' + selectedVoice.lang : '';
      }

      if ('speechSynthesis' in window) {
        window.speechSynthesis.onvoiceschanged = loadVoice;
        loadVoice();
      }

      function stopSpeaking() {
        if ('speechSynthesis' in window) window.speechSynthesis.cancel();
        window.clearInterval(speak.poller);
        isSpeaking = false;
        document.body.classList.remove('speaking');
      }

      function speak(text) {
        showBubble(text);
        if (muted || !('speechSynthesis' in window)) return;
        stopSpeaking();
        var utterance = new SpeechSynthesisUtterance(text);
        if (!selectedVoice) loadVoice();
        if (selectedVoice) utterance.voice = selectedVoice;
        utterance.lang = selectedVoice ? selectedVoice.lang : 'zh-TW';
        utterance.rate = Math.max(.9, ttsRate * .95);
        utterance.pitch = .95;
        utterance.onend = function () {
          isSpeaking = false;
          document.body.classList.remove('speaking');
          window.clearInterval(speak.poller);
        };
        window.speechSynthesis.speak(utterance);
        isSpeaking = true;
        document.body.classList.add('speaking');
        var startedAt = performance.now();
        speak.poller = window.setInterval(function () {
          var active = window.speechSynthesis.speaking || window.speechSynthesis.pending;
          if ((performance.now() - startedAt > 900 && !active) || performance.now() - startedAt > 18000) {
            isSpeaking = false;
            document.body.classList.remove('speaking');
            window.clearInterval(speak.poller);
          }
        }, 160);
      }

      function handleUserText(text) {
        var clean = String(text || '').trim();
        if (clean) showBubble('你：' + clean, 2400);
        window.setTimeout(function () { speak(answer(clean)); }, 180);
      }

      function setMicState(active) {
        var button = document.getElementById('btn-mic');
        var suggestions = document.getElementById('suggestions');
        listening = active;
        document.body.classList.toggle('listening', active);
        button.classList.toggle('listening', active);
        button.textContent = active ? '聆聽中' : '說話';
        suggestions.style.display = active ? 'none' : 'flex';
      }

      function startListening() {
        if (!SpeechRecognitionApi) {
          speak('你的瀏覽器目前不支援語音辨識。建議使用 Chrome 桌機版，或直接點下方常見問題。');
          return;
        }
        if (listening && recognition) {
          recognition.stop();
          return;
        }
        try {
          recognition = new SpeechRecognitionApi();
        } catch (error) {
          speak('語音辨識啟動失敗，請改用 Chrome 桌機版再試一次。');
          return;
        }
        recognition.lang = 'zh-TW';
        recognition.interimResults = true;
        recognition.continuous = false;
        recognition.maxAlternatives = 1;
        recognition.onstart = function () {
          setMicState(true);
          showBubble('正在聆聽。Chrome 可能會使用瀏覽器廠商雲端處理語音，本站不會自行儲存你的語音內容。', 9000);
        };
        recognition.onresult = function (event) {
          var text = '';
          for (var i = 0; i < event.results.length; i += 1) text += event.results[i][0].transcript;
          var last = event.results[event.results.length - 1];
          if (last.isFinal) handleUserText(text);
          else showBubble('你：' + text, 2600);
        };
        recognition.onerror = function (event) {
          setMicState(false);
          showBubble(event.error === 'not-allowed' ? '需要允許麥克風權限，我才能聽你說話。' : '剛剛沒有聽清楚，可以再試一次。');
        };
        recognition.onend = function () { setMicState(false); };
        recognition.start();
      }

      function renderSuggestions() {
        var box = document.getElementById('suggestions');
        var items = ['享哥提供哪些服務', 'n8n 可以做什麼', '怎麼預約諮詢', '費用怎麼算'];
        items.forEach(function (item) {
          var button = document.createElement('button');
          button.type = 'button';
          button.className = 'suggestion';
          button.textContent = item;
          button.addEventListener('click', function () { handleUserText(item); });
          box.appendChild(button);
        });
      }

      function resizeAvatar() {
        window.__avatarLayout = {
          width: document.getElementById('stage').clientWidth,
          height: document.getElementById('stage').clientHeight
        };
      }

      document.getElementById('btn-close').addEventListener('click', function () {
        stopSpeaking();
        post('close');
      });
      document.getElementById('btn-mic').addEventListener('click', startListening);
      document.getElementById('btn-mute').addEventListener('click', function () {
        muted = !muted;
        this.textContent = muted ? '靜音' : '聲音';
        this.setAttribute('aria-pressed', String(muted));
        if (muted) stopSpeaking();
        showBubble(muted ? '已靜音。' : '已恢復語音。');
      });
      document.getElementById('btn-speed').addEventListener('click', function () {
        var steps = [.9, 1, 1.15, 1.3];
        var current = steps.indexOf(ttsRate);
        ttsRate = steps[(current + 1) % steps.length] || 1;
        this.textContent = ttsRate.toFixed(1) + 'x';
        showBubble('語速已調整為 ' + ttsRate.toFixed(1) + ' 倍。');
      });
      document.getElementById('assistant-avatar').addEventListener('click', function () {
        speak('你好，我是享哥的 AI 虛擬助理。你可以問我服務內容、企業內訓或自動化流程。');
      });
      window.addEventListener('message', function (event) {
        var data = event.data || {};
        if (data.ns === 'hsiang-avatar-host' && data.type === 'say') speak(String(data.text || '').slice(0, 500));
        if (data.ns === 'hsiang-avatar-host' && data.type === 'open') {
          window.requestAnimationFrame(function () {
            resizeAvatar();
            window.setTimeout(resizeAvatar, 160);
          });
        }
      });

      renderSuggestions();
      window.__avatarModel = { type: 'svg-assistant', brand: 'hsiang' };
      window.__resizeAvatar = resizeAvatar;
      resizeAvatar();
      window.addEventListener('resize', resizeAvatar);
      window.setTimeout(function () {
        showBubble('你好，我是享哥的 AI 虛擬助理。可以先問我服務內容、n8n 自動化、費用或預約諮詢。', 8200);
      }, 600);
    })();
  </script>
</body>
</html>

